def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'

    def rs(n, k):
        return ''.join(rng.choice(letters[:k]) for _ in range(n))

    tests = ['a', 'ab', 'aa', 'abc', 'aab', 'abab', 'zzzz', 'abcabc', 'abcdefghijklmnopqrstuvwxyz']
    for n in (3, 4, 5, 6, 8, 10, 12, 15, 20, 30):
        for k in (2, 3, 26):
            tests.append(rs(n, k))
    for n in (60, 120, 200):
        for k in (2, 5, 26):
            tests.append(rs(n, k))
    tests.append(rs(2000, 26))
    tests.append(rs(5000, 3))
    N = 100000
    tests.append(rs(N, 26))
    tests.append(rs(N, 2))
    tests.append('a' * N)
    tests.append(''.join(letters[i % 26] for i in range(N)))
    return tests

